const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let state=null,currentUser=null,currentView='public';
async function api(url,opt={}){let r=await fetch(url,{headers:{'Content-Type':'application/json'},...opt}),j=await r.json();if(!r.ok)throw new Error(j.error==='AUTH_REQUIRED'?'AUTH_REQUIRED':j.message||j.error);return j}
const panelViews=['dashboard','myads','create','radar','connections','results','admin'];
function view(id){closeModal();if(panelViews.includes(id)&&!currentUser)id='login';if(id==='admin'&&currentUser?.role!=='admin')id='dashboard';currentView=id;try{localStorage.setItem('anunciae:lastView',id)}catch{}$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));shell();scrollTo(0,0);if(id==='admin')loadAdmin();if(id==='results')loadResults();if(id==='dashboard')loadDashboardSummary()}
function bindViews(){$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-action="brand"]').forEach(b=>b.onclick=()=>openBrandManual());$$('[data-action="company"]').forEach(b=>b.onclick=()=>openCompany());$$('[data-action="profile"]').forEach(b=>b.onclick=()=>openProfile());$$('[data-action="change-plan"]').forEach(b=>b.onclick=()=>openPlanManager());$$('[data-action="change-password"]').forEach(b=>b.onclick=()=>openPasswordManager())}bindViews();
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function syncHomeHeader(){document.body.classList.toggle('homeHeaderScrolled',currentView==='public'&&window.scrollY>24)}
window.addEventListener('scroll',syncHomeHeader,{passive:true});
function shell(){let logged=!!currentUser,inPanel=panelViews.includes(currentView);$('#userNav').hidden=!(logged&&inPanel);$('#logout').hidden=!logged;$('#panelAccess').hidden=!(logged&&!inPanel);$('#loginAccess').hidden=logged;$('#registerAccess').hidden=logged;$('#adminNav').hidden=!(logged&&currentUser.role==='admin'&&inPanel);syncHomeHeader()}
async function loadState(){state=await api('/api/state');currentUser=state.user;let period90=$('#resultsPeriod option[value="90"]');if(period90)period90.disabled=state.entitlements?.results?.maxHistoryDays<90;$('#welcome').textContent=`Olá, ${currentUser.name}. Plano ${state.entitlements?.planName||''}.  Você define o objetivo e o limite. O Public.IA cuida do restante dentro das regras autorizadas.`;render();shell()}
