async function openTikTokManager(){openModal('Gerenciar TikTok Ads','CONEXÃO TIKTOK',`<div class="metaManager tiktokManager"><div class="metaLoading">Consultando as contas autorizadas no TikTok Ads…</div></div>`);try{let a=await api('/api/integrations/tiktok/assets'),root=$('.tiktokManager'),opts=`<option value="">Selecione</option>`+a.accounts.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(a.selected.accountId)?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('');root.innerHTML=`<div class="metaConnected"><span class="metaDot"></span><div><strong>TikTok Ads conectado</strong><small>Marketing API ${esc(a.apiVersion)} · preparação segura</small></div></div><p class="metaHelp">Escolha a conta TikTok Ads que a PublicIA poderá usar. Nenhuma campanha será criada ou publicada nesta etapa.</p><div class="metaAssetGrid"><label>Conta TikTok Ads<select id="tiktokAdsAccount">${opts}</select></label></div><div class="metaInfo">Encontradas ${a.accounts.length} conta(s) TikTok Ads acessíveis.</div><div class="metaActions"><button class="primary saveTikTokAssets">Salvar seleção</button><button class="danger disconnectTikTok">Desconectar TikTok</button></div>`;let account=$('#tiktokAdsAccount');$('.saveTikTokAssets').onclick=async()=>{if(!account.value)return alert('Selecione uma conta TikTok Ads.');let btn=$('.saveTikTokAssets');btn.disabled=true;try{await api('/api/integrations/tiktok/selection',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:account.value})});await loadState();closeModal()}catch(e){alert(e.message);btn.disabled=false}};$('.disconnectTikTok').onclick=async()=>{if(!confirm('Desconectar o TikTok Ads desta conta da PublicIA?'))return;await api('/api/integrations/tiktok',{method:'DELETE'});closeModal();await loadState()}}catch(e){$('.tiktokManager').innerHTML=`<div class="metaError"><strong>TikTok Ads preparado.</strong><p>${esc(e.message)}</p><p>A conexão ficará disponível assim que o Developer Profile e o aplicativo forem aprovados e as credenciais forem configuradas.</p><button class="danger disconnectTikTok">Desconectar TikTok</button></div>`;$('.disconnectTikTok').onclick=async()=>{if(confirm('Desconectar o TikTok Ads desta conta da PublicIA?')){await api('/api/integrations/tiktok',{method:'DELETE'});closeModal();await loadState()}}}}
async function openXManager(){openModal('Gerenciar X Ads','CONEXÃO X',`<div class="metaManager xManager"><div class="metaLoading">Consultando as contas autorizadas no X Ads…</div></div>`);try{let a=await api('/api/integrations/x/assets'),root=$('.xManager'),opts=`<option value="">Selecione</option>`+a.accounts.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(a.selected.accountId)?'selected':''}>${esc(x.name)} · ${esc(x.id)}${x.currency?' · '+esc(x.currency):''}</option>`).join('');root.innerHTML=`<div class="metaConnected"><span class="metaDot"></span><div><strong>X conectado</strong><small>${a.adsApiStatus==='standard'?'Standard Ads API · OAuth 1.0a autorizado · leitura e gestão disponíveis':'Conexão anterior em modo leitura · reconecte uma vez para Standard Ads API'}</small></div></div><p class="metaHelp">Escolha a conta X Ads que o Public.IA poderá usar. Nada será criado ou publicado nesta etapa.</p><div class="metaAssetGrid"><label>Conta X Ads<select id="xAdsAccount">${opts}</select></label></div><div class="metaInfo">Encontradas ${a.accounts.length} conta(s) X Ads acessíveis pela autorização concedida.</div><div class="metaActions">${a.adsApiStatus!=='standard'?'<button class="primary migrateXStandard">Migrar para Standard Ads API</button>':'<button class="primary saveXAssets">Salvar seleção</button>'}<button class="danger disconnectX">Desconectar X</button></div>`;let account=$('#xAdsAccount');let migrateBtn=$('.migrateXStandard');if(migrateBtn)migrateBtn.onclick=()=>{window.location.href='/api/integrations/x/connect'};let saveBtn=$('.saveXAssets');if(saveBtn)saveBtn.onclick=async()=>{if(!account.value)return alert('Selecione uma conta X Ads.');let btn=saveBtn;btn.disabled=true;try{await api('/api/integrations/x/selection',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:account.value})});await loadState();closeModal()}catch(e){alert(e.message);btn.disabled=false}};$('.disconnectX').onclick=async()=>{if(!confirm('Desconectar o X desta conta do Public.IA?'))return;await api('/api/integrations/x',{method:'DELETE'});closeModal();await loadState()}}catch(e){$('.xManager').innerHTML=`<div class="metaError"><strong>X Ads precisa de atenção.</strong><p>Não foi possível listar as contas de anúncios.</p><p>${esc(e.message)}</p><p>Nenhuma campanha será criada, alterada, ativada ou publicada durante esta validação.</p><button class="secondary retryXAssets">Tentar novamente</button><button class="danger disconnectX">Desconectar X</button></div>`;$('.retryXAssets').onclick=()=>openXManager();$('.disconnectX').onclick=async()=>{if(confirm('Desconectar o X desta conta do Public.IA?')){await api('/api/integrations/x',{method:'DELETE'});closeModal();await loadState()}}}}

async function openLinkedinManager(){openModal('Gerenciar LinkedIn Ads','CONEXÃO LINKEDIN',`<div class="metaManager linkedinManager"><div class="metaLoading">Consultando as contas autorizadas no LinkedIn Ads…</div></div>`);try{let a=await api('/api/integrations/linkedin/assets'),root=$('.linkedinManager'),opts=`<option value="">Selecione</option>`+a.accounts.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(a.selected.accountId)?'selected':''}>${esc(x.name)} · ${esc(x.id)}${x.currency?' · '+esc(x.currency):''}${x.role?' · '+esc(x.role):''}</option>`).join(''),writeReady=!a.readOnly;root.innerHTML=`<div class="metaConnected"><span class="metaDot"></span><div><strong>LinkedIn Ads conectado</strong><small>OAuth 2.0 ativo · Advertising API ${esc(a.apiVersion)} · ${writeReady?'leitura e gestão':'somente leitura'}</small></div></div><p class="metaHelp">Escolha a conta LinkedIn Ads que a PublicIA poderá usar. Para a homologação solicitada pelo LinkedIn, a conexão precisa autorizar <b>rw_ads</b>.</p><div class="metaAssetGrid"><label>Conta LinkedIn Ads<select id="linkedinAdsAccount">${opts}</select></label></div><div class="metaInfo">Encontradas ${a.accounts.length} conta(s) LinkedIn Ads acessíveis. No Development Tier, a conta precisa estar mapeada ao aplicativo.</div>${writeReady?`<div class="publicationNotice"><strong>Homologação LinkedIn</strong><br>O teste cria somente uma campanha em <b>RASCUNHO</b>, sem ativar anúncios e sem gerar gasto. Depois permite editar o nome para demonstrar criação e edição no vídeo solicitado pelo LinkedIn.</div><label class="checkRow"><input type="checkbox" id="linkedinNonPolitical" checked> Confirmo que esta demonstração não é publicidade política.</label><div class="metaActions"><button class="secondary linkedinDemoCreate">${a.demoDraft?.campaignId?'Rascunho criado':'Criar rascunho de homologação'}</button>${a.demoDraft?.campaignId?`<button class="secondary linkedinDemoEdit">Editar rascunho</button><button class="danger linkedinDemoDelete">Excluir rascunho de homologação</button>`:''}</div>${a.demoDraft?.campaignId?`<div class="metaInfo">Campanha: ${esc(a.demoDraft.name||'PublicIA · Demonstração LinkedIn')} · ID ${esc(a.demoDraft.campaignId)} · DRAFT.</div>`:''}`:`<div class="publicationNotice"><strong>Precisamos liberar a escrita para o vídeo de homologação.</strong><br>Sua autorização atual é somente leitura. Reconecte uma vez para conceder <b>rw_ads</b>. Isso não publica nenhum anúncio.</div><button class="primary linkedinReauthorize">Autorizar gestão no LinkedIn</button>`}<div class="metaActions"><button class="primary saveLinkedinAssets">Salvar seleção</button><button class="danger disconnectLinkedin">Desconectar LinkedIn</button></div>`;let account=$('#linkedinAdsAccount');$('.saveLinkedinAssets').onclick=async()=>{if(!account.value)return alert('Selecione uma conta LinkedIn Ads.');let btn=$('.saveLinkedinAssets');btn.disabled=true;try{await api('/api/integrations/linkedin/selection',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:account.value})});await loadState();closeModal()}catch(e){alert(e.message);btn.disabled=false}};let reauth=$('.linkedinReauthorize');if(reauth)reauth.onclick=()=>window.location.href='/api/integrations/linkedin/connect';let create=$('.linkedinDemoCreate');if(create)create.onclick=async()=>{if(a.demoDraft?.campaignId)return alert('O rascunho já foi criado. Use “Editar rascunho”.');if(!account.value)return alert('Selecione e salve primeiro a conta LinkedIn Ads.');if(!$('#linkedinNonPolitical')?.checked)return alert('Confirme que a demonstração não é publicidade política.');if(!confirm('Criar uma campanha LinkedIn em RASCUNHO para homologação? Ela não será ativada e não deverá gerar gasto.'))return;create.disabled=true;try{let r=await api('/api/integrations/linkedin/demo-draft',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmSafeDraft:true,nonPoliticalConfirmed:true})});alert('Rascunho criado no LinkedIn. ID: '+r.demoDraft.campaignId);await openLinkedinManager()}catch(e){alert(e.message);create.disabled=false}};let edit=$('.linkedinDemoEdit');if(edit)edit.onclick=async()=>{let name=prompt('Novo nome para demonstrar a edição:','PublicIA · Demonstração LinkedIn · editada');if(!name)return;edit.disabled=true;try{await api('/api/integrations/linkedin/demo-draft',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});alert('Rascunho editado no LinkedIn com sucesso.');await openLinkedinManager()}catch(e){alert(e.message);edit.disabled=false}};let delDraft=$('.linkedinDemoDelete');if(delDraft)delDraft.onclick=async()=>{if(!confirm('Excluir o rascunho de homologação do LinkedIn? A campanha e o grupo em DRAFT serão removidos para permitir uma nova gravação da demonstração.'))return;delDraft.disabled=true;try{await api('/api/integrations/linkedin/demo-draft',{method:'DELETE'});alert('Rascunho de homologação excluído do LinkedIn com sucesso.');await openLinkedinManager()}catch(e){alert(e.message);delDraft.disabled=false}};$('.disconnectLinkedin').onclick=async()=>{if(!confirm('Desconectar o LinkedIn Ads desta conta da PublicIA?'))return;await api('/api/integrations/linkedin',{method:'DELETE'});closeModal();await loadState()}}catch(e){$('.linkedinManager').innerHTML=`<div class="metaError"><strong>LinkedIn autorizado, mas não foi possível consultar as contas Ads.</strong><p>${esc(e.message)}</p><p>Confirme também o mapeamento da conta em Products → Advertising API → View Ad Accounts.</p><button class="secondary retryLinkedinAssets">Tentar novamente</button><button class="danger disconnectLinkedin">Desconectar LinkedIn</button></div>`;$('.retryLinkedinAssets').onclick=()=>openLinkedinManager();$('.disconnectLinkedin').onclick=async()=>{if(confirm('Desconectar o LinkedIn Ads desta conta da PublicIA?')){await api('/api/integrations/linkedin',{method:'DELETE'});closeModal();await loadState()}}}}
async function openGoogleManager(){openModal('Gerenciar Google Ads','CONEXÃO GOOGLE',`<div class="metaManager googleManager"><div class="metaLoading">Consultando as contas autorizadas no Google Ads…</div></div>`);try{let a=await api('/api/integrations/google/assets'),root=$('.googleManager'),opts=`<option value="">Selecione</option>`+a.customers.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(a.selected.customerId)?'selected':''}>${esc(x.name)} · ${esc(x.id)}${x.currency?' · '+esc(x.currency):''}${x.manager?' · Gerenciadora':''}</option>`).join('');root.innerHTML=`<div class="metaConnected"><span class="metaDot"></span><div><strong>Google Ads conectado</strong><small>Autorização OAuth ativa · API ${esc(a.apiVersion)}</small></div></div><p class="metaHelp">Escolha a conta Google Ads que o Public.IA poderá usar. Nada será criado ou publicado nesta etapa.</p><div class="metaAssetGrid"><label>Conta Google Ads<select id="googleCustomer">${opts}</select></label></div><div class="metaInfo">Encontradas ${a.customers.length} conta(s) diretamente acessíveis pela autorização concedida.</div><div class="metaActions"><button class="primary saveGoogleAssets">Salvar seleção</button><button class="secondary validateGooglePublication">Validar publicação</button><button class="danger disconnectGoogle">Desconectar Google Ads</button></div><div class="googleValidationResult"></div>`;let customer=$('#googleCustomer');$('.validateGooglePublication').onclick=async()=>{let btn=$('.validateGooglePublication'),out=$('.googleValidationResult');btn.disabled=true;out.innerHTML='<p class="metaHelp">Validando permissão de escrita sem criar campanha e sem gerar cobrança…</p>';try{let r=await api('/api/integrations/google/validate-publication',{method:'POST'});out.innerHTML=`<div class="metaInfo"><strong>Publicação validada.</strong><br>${esc(r.message)}</div>`}catch(e){out.innerHTML=`<div class="metaError"><strong>Publicação ainda não liberada.</strong><p>${esc(e.message)}</p></div>`}finally{btn.disabled=false}};$('.saveGoogleAssets').onclick=async()=>{if(!customer.value)return alert('Selecione uma conta Google Ads.');let btn=$('.saveGoogleAssets');btn.disabled=true;try{await api('/api/integrations/google/selection',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({customerId:customer.value})});await loadState();closeModal()}catch(e){alert(e.message);btn.disabled=false}};$('.disconnectGoogle').onclick=async()=>{if(!confirm('Desconectar o Google Ads desta conta do Public.IA?'))return;await api('/api/integrations/google',{method:'DELETE'});closeModal();await loadState()}}catch(e){$('.googleManager').innerHTML=`<div class="metaError"><strong>Não foi possível consultar as contas do Google Ads.</strong><p>${esc(e.message)}</p><p>A conexão OAuth não foi removida.</p><button class="secondary retryGoogleAssets">Tentar novamente</button><button class="danger disconnectGoogle">Desconectar Google Ads</button></div>`;$('.retryGoogleAssets').onclick=()=>openGoogleManager();$('.disconnectGoogle').onclick=async()=>{if(confirm('Desconectar o Google Ads desta conta do Public.IA?')){await api('/api/integrations/google',{method:'DELETE'});closeModal();await loadState()}}}}

async function openMetaManager(){openModal('Gerenciar Meta Ads','CONEXÃO META',`<div class="metaManager"><div class="metaLoading">Consultando os ativos autorizados na Meta…</div></div>`);try{let a=await api('/api/integrations/meta/assets'),root=$('.metaManager'),opt=(xs,val,label)=>`<option value="">Selecione</option>`+xs.map(x=>`<option value="${esc(x.id)}" ${x.id===val?'selected':''}>${esc(label(x))}</option>`).join(''),renderAssets=(data)=>{let ad=$('#metaAdAccount'),page=$('#metaPage');ad.innerHTML=opt(data.adAccounts,data.selected.adAccountId,x=>`${x.name} · ${x.account_id||x.id}${x.currency?' · '+x.currency:''}`);page.innerHTML=opt(data.pages,data.selected.pageId,x=>x.name);$('.metaInfo').textContent=data.filteredByBusiness?`Vinculados a ${data.selectedBusiness.name}: ${data.adAccounts.length} conta(s) de anúncios e ${data.pages.length} Página(s).`:`Encontrados: ${data.businesses.length} empresa(s), ${data.adAccounts.length} conta(s) de anúncios e ${data.pages.length} Página(s) dentro da autorização concedida.`;ad.disabled=page.disabled=false};root.innerHTML=`<div class="metaConnected"><span class="metaDot"></span><div><strong>Meta Ads conectado</strong><small>${a.profile?.name?`Conta Meta: ${esc(a.profile.name)}`:'Autorização ativa e validada.'}</small></div></div><p class="metaHelp">Escolha primeiro a empresa / portfólio. As contas de anúncios e Páginas serão filtradas pelos ativos realmente vinculados a ela. Nada será publicado nesta etapa.</p><div class="metaAssetGrid"><label>Empresa / portfólio<select id="metaBusiness">${opt(a.businesses,a.selected.businessId,x=>x.name)}</select></label><label>Conta de anúncios<select id="metaAdAccount">${opt(a.adAccounts,a.selected.adAccountId,x=>`${x.name} · ${x.account_id||x.id}${x.currency?' · '+x.currency:''}`)}</select></label><label>Página do Facebook<select id="metaPage">${opt(a.pages,a.selected.pageId,x=>x.name)}</select></label></div><div class="metaInfo">Encontrados: ${a.businesses.length} empresa(s), ${a.adAccounts.length} conta(s) de anúncios e ${a.pages.length} Página(s) dentro da autorização concedida.</div><div class="metaValidation" hidden></div><div class="metaActions"><button class="primary saveMetaAssets">Salvar seleção</button><button class="secondary validateMeta">Validar estrutura</button><button class="danger disconnectMeta">Desconectar Meta Ads</button></div>`;let biz=$('#metaBusiness'),ad=$('#metaAdAccount'),page=$('#metaPage');if(biz.value){ad.disabled=page.disabled=true;let filtered=await api('/api/integrations/meta/assets?businessId='+encodeURIComponent(biz.value));renderAssets(filtered)}biz.onchange=async()=>{ad.innerHTML='<option>Consultando…</option>';page.innerHTML='<option>Consultando…</option>';ad.disabled=page.disabled=true;if(!biz.value){ad.innerHTML='<option value="">Selecione primeiro a empresa / portfólio</option>';page.innerHTML='<option value="">Selecione primeiro a empresa / portfólio</option>';$('.metaInfo').textContent='Selecione uma empresa / portfólio para carregar somente os ativos vinculados.';return}try{let filtered=await api('/api/integrations/meta/assets?businessId='+encodeURIComponent(biz.value));renderAssets(filtered)}catch(e){ad.innerHTML='<option value="">Não foi possível consultar</option>';page.innerHTML='<option value="">Não foi possível consultar</option>';$('.metaInfo').textContent=e.message}};$('.saveMetaAssets').onclick=async()=>{let btn=$('.saveMetaAssets');if(!biz.value)return alert('Selecione a empresa / portfólio.');if(!ad.value)return alert('Selecione a conta de anúncios vinculada à empresa.');if(!page.value)return alert('Selecione a Página do Facebook vinculada à empresa.');btn.disabled=true;try{await api('/api/integrations/meta/selection',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId:biz.value,adAccountId:ad.value,pageId:page.value})});btn.textContent='Seleção salva ✓';await loadState()}catch(e){alert(e.message);btn.disabled=false}};$('.validateMeta').onclick=async()=>{let btn=$('.validateMeta'),box=$('.metaValidation');btn.disabled=true;btn.textContent='Validando…';box.hidden=false;box.innerHTML='<p>Consultando a Meta em tempo real…</p>';try{let v=await api('/api/integrations/meta/validate',{method:'POST'});box.innerHTML=`<strong>${v.ready?'Estrutura pronta para a próxima etapa':'Há itens que precisam de atenção'}</strong><div class="metaCheckList">${v.checks.map(c=>`<div class="metaCheck ${c.warning?'warn':c.ok?'ok':'fail'}"><span>${c.warning?'!':c.ok?'✓':'×'}</span><div><b>${esc(c.label)}</b><small>${esc(c.detail||'')}</small></div></div>`).join('')}</div><small>Validação ao vivo · Marketing API ${esc(v.apiVersion)} · Nenhuma campanha foi criada ou publicada.</small>`}catch(e){box.innerHTML=`<strong>Não foi possível concluir a validação.</strong><p>${esc(e.message)}</p>`}finally{btn.disabled=false;btn.textContent='Validar estrutura'}};$('.disconnectMeta').onclick=async()=>{if(!confirm('Desconectar a conta Meta Ads desta conta do Public.IA?'))return;await api('/api/integrations/meta',{method:'DELETE'});closeModal();await loadState()}}catch(e){$('.metaManager').innerHTML=`<div class="metaError"><strong>Não foi possível consultar os ativos da Meta.</strong><p>${esc(e.message)}</p><p>A conexão não foi removida. Você pode tentar novamente ou desconectar manualmente.</p><button class="secondary retryMetaAssets">Tentar novamente</button><button class="danger disconnectMeta">Desconectar Meta Ads</button></div>`;$('.retryMetaAssets').onclick=()=>openMetaManager();$('.disconnectMeta').onclick=async()=>{if(confirm('Desconectar a conta Meta Ads desta conta do Public.IA?')){await api('/api/integrations/meta',{method:'DELETE'});closeModal();await loadState()}}}}
